        if(np > 1) chips += '<br>' + ['all'].concat(pgs().map(function(_, i){ return i; })).map(function(k){ return '<button class="g' + (which === k ? ' on' : '') + '" data-pg="' + k + '">' + (k === 'all' ? 'All pages' : 'Page ' + (k + 1)) + '</button>'; }).join('');
        chips += '</div>';
