        q.innerHTML = '<div class="sheet"><div class="ttl">Crop image</div><canvas width="' + cw + '" height="' + ch + '"></canvas><div>' +
          [['Free', 0], ['1:1', 1], ['16:9', 16 / 9], ['9:16', 9 / 16], ['4:3', 4 / 3], ['3:4', 3 / 4]].map(function(c){ return '<button class="g' + (c[1] === 0 ? ' on' : '') + '" data-r="' + c[1] + '">' + c[0] + '</button>'; }).join('') +
          '</div><div class="two" style="margin-top:10px"><label>W (px)<input id="iw" type="number"></label><label>H (px)<input id="ih" type="number"></label></div><div class="two"><button class="xb gh" id="rs">Reset</button><button class="xb" id="ap">Apply</button></div></div>';
