    P.onchange = function(){ if(P.value !== 'offline' && (!M.value || M.value === DEF.gemini || M.value === DEF.claude)) M.value = DEF[P.value]; sync(); };
    d.querySelector('#cgC').onclick = function(){ d.remove(); };
