      '<div class="ph-ch">' + fm + '</div>' + (S.fmt === 'zip' ? '<div class="ph-r"><label>Inside ZIP<select id="rZ"><option>jpg</option><option>png</option><option>webp</option></select></label></div>' : '') +
      '<div class="ph-r"><button class="ph-b" id="rA">Apply resize</button><button class="ph-b go" id="rX">⬇ Export</button></div><div class="ph-m" id="rMsg"></div>';
    var q = function(s){ return p.querySelector(s); }, info = function(){ q('#rI').textContent = S.pxW + ' × ' + S.pxH + ' px'; };
