    var asp = function(){ return S.cv ? S.cv.width / S.cv.height : 1; };
    q('#rW').oninput = function(){ S.pxW = u2px(+this.value); if(S.lock){ S.pxH = Math.max(1, Math.round(S.pxW / asp())); q('#rH').value = fmtN(px2u(S.pxH)); } info(); };
    q('#rH').oninput = function(){ S.pxH = u2px(+this.value); if(S.lock){ S.pxW = Math.max(1, Math.round(S.pxH * asp())); q('#rW').value = fmtN(px2u(S.pxW)); } info(); };
