    q('#rD').oninput = function(){ var o = S.unit !== 'px' ? { w:px2u(S.pxW), h:px2u(S.pxH) } : null; S.dpi = Math.max(1, +this.value || 1); if(o){ S.pxW = u2px(o.w); S.pxH = u2px(o.h); info(); } };
