      '<div style="margin:8px 12px 0;font-size:12px;color:#9a9aa3;line-height:1.5">Boxed tools appear in the toolbar. Tap a tool to select or unselect it. Press and hold a tool, then drag to rearrange.</div>' +
      '<div class="cz-t"><button class="ph-c" id="czA">Select all</button><button class="ph-c" id="czN">Unselect all</button><button class="ph-c" id="czR">↺ Default</button></div><div id="phCzL"></div>';
